const CK = "2026-11-03", BY = "ai-ref";
const BRIT = (slug, t) => ({ t: `Britannica — ${t}`, u: `https://www.britannica.com/${slug}` });
const WHC = (n, t) => ({ t: `UNESCO World Heritage — ${t}`, u: `https://whc.unesco.org/en/list/${n}` });
