const base = (id, area, game, kind, d, q, exp, src, more) => ({ id, area, game, kind, d, q, exp, src: Array.isArray(src) ? src : [src], checked: CK, by: BY, ver: 1, status: "checked", assets: [], tags: ["7차"], ...more });
const TR = {};
const add = (item, ja, en) => { TR[item.id] = { ja, en }; return item; };
const sort = (id, area, d, q, bins, items, exp, src, ja, en) => add(base(id, area, "sortfac", "sort", d, q, exp, src, { bins, items }), ja, en);
const kase = (id, area, d, q, clues, opts, exp, src, ja, en) => add(base(id, area, "detective", "case", d, q, exp, src, { clues, opts }), ja, en);
const link = (id, area, d, q, pairs, exp, src, ja, en) => add(base(id, area, "linker", "link", d, q, exp, src, { pairs }), ja, en);
const where = (id, d, place, clues, codes, exp, src, ja, en) => add(base(id, "geo", "where", "where", d, "여행 엽서가 도착했어요. 이 장소가 있는 나라를 지도에서 고르세요.", exp, src, { place, clues, codes }), { q: "旅のはがきが届きました。この場所がある国を地図から選びましょう。", ...ja }, { q: "A travel postcard arrived. Pick the country where this place is.", ...en });
const katch = (id, area, d, topic, items, exp, src, ja, en) => add(base(id, area, "catch", "catch", d, `${topic} 떨어지는 것 중 맞는 것만 받으세요.`, exp, src, { topic, items }), { q: `${ja.topic} 落ちてくるものから正しいものだけキャッチしましょう。`, ...ja }, { q: `${en.topic} Catch only the right ones as they fall.`, ...en });
const reveal = (id, area, d, clues, opts, exp, src, ja, en) => add(base(id, area, "reveal", "reveal", d, "단서를 보고 정체를 맞혀 보세요.", exp, src, { clues, opts }), { q: "手がかりを見て正体を当てましょう。", ...ja }, { q: "Use the clues to work out what this is.", ...en });
const map = (id, d, name, codes, exp, src, ja, en) => add(base(id, "geo", "world", "map", d, `지도에서 ${name}${/[가-힣]$/.test(name) && (name.charCodeAt(name.length - 1) - 0xac00) % 28 ? "을" : "를"} 찾아 누르세요.`, exp, src, { codes }), ja, en);
const order = (id, area, d, q, events, exp, src, ja, en) => add(base(id, area, "timeline", "order", d, q, exp, src, { events }), ja, en);
const T = (a, b) => [a, b];

